"use server";

import { AuthError } from "next-auth";
import { z } from "zod";
import { signIn, signOut } from "@/auth";
import { createUser, EmailTakenError } from "@/lib/users";

export type FormState = { error?: string };

// Only allow same-site relative redirects.
function safeRedirect(to: FormDataEntryValue | null) {
  return typeof to === "string" && to.startsWith("/") && !to.startsWith("//")
    ? to
    : "/dashboard";
}

export async function signInAction(_: FormState, form: FormData): Promise<FormState> {
  try {
    await signIn("credentials", {
      email: form.get("email"),
      password: form.get("password"),
      redirectTo: safeRedirect(form.get("callbackUrl")),
    });
  } catch (e) {
    if (e instanceof AuthError) return { error: "Invalid email or password" };
    throw e; // redirect
  }
  return {};
}

const signUpSchema = z.object({
  name: z.string().trim().min(1, "Name is required").max(100),
  email: z.string().trim().email("Enter a valid email"),
  password: z.string().min(8, "Password must be at least 8 characters").max(72),
});

export async function signUpAction(_: FormState, form: FormData): Promise<FormState> {
  const parsed = signUpSchema.safeParse({
    name: form.get("name"),
    email: form.get("email"),
    password: form.get("password"),
  });
  if (!parsed.success) return { error: parsed.error.issues[0].message };
  try {
    await createUser(parsed.data);
  } catch (e) {
    if (e instanceof EmailTakenError) return { error: e.message };
    throw e;
  }
  return signInAction({}, form);
}

export async function googleSignInAction() {
  await signIn("google", { redirectTo: "/dashboard" });
}

export async function signOutAction() {
  await signOut({ redirectTo: "/" });
}
EOF
