"use client";

import Link from "next/link";
import { useActionState } from "react";
import { googleSignInAction, signInAction, signUpAction } from "./actions";

const input = "mt-1 w-full rounded border border-black/20 bg-transparent p-2 text-sm dark:border-white/25";
const button = "w-full rounded bg-foreground p-2 text-sm font-medium text-background disabled:opacity-50";

export function AuthForm({ mode, callbackUrl }: { mode: "signin" | "signup"; callbackUrl?: string }) {
  const signup = mode === "signup";
  const [state, action, pending] = useActionState(signup ? signUpAction : signInAction, {});

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{signup ? "Create your account" : "Sign in to Notely"}</h1>

      <form action={action} className="mt-6 space-y-4">
        <input type="hidden" name="callbackUrl" value={callbackUrl ?? ""} />
        {signup && (
          <label className="block text-sm">
            Name
            <input name="name" required autoComplete="name" className={input} />
          </label>
        )}
        <label className="block text-sm">
          Email
          <input name="email" type="email" required autoComplete="email" className={input} />
        </label>
        <label className="block text-sm">
          Password
          <input
            name="password"
            type="password"
            required
            minLength={signup ? 8 : undefined}
            autoComplete={signup ? "new-password" : "current-password"}
            className={input}
          />
        </label>
        {state.error && <p role="alert" className="text-sm text-red-600">{state.error}</p>}
        <button disabled={pending} className={button}>{signup ? "Sign up" : "Sign in"}</button>
      </form>

      <form action={googleSignInAction} className="mt-3">
        <button className="w-full rounded border border-black/20 p-2 text-sm dark:border-white/25">
          Continue with Google
        </button>
      </form>

      <p className="mt-6 text-sm opacity-70">
        {signup ? "Already have an account? " : "No account yet? "}
        <Link className="underline" href={signup ? "/signin" : "/signup"}>
          {signup ? "Sign in" : "Sign up"}
        </Link>
      </p>
    </main>
  );
}
